"""Guion tecnico de «Por que desaparecieron los kioscos y los estancos no» — planos libres.

    python kioscos.py            -> vox/kioscos.spec.json

Los numeros de fragmento son los de la locucion (85). Fuentes: config/guion_kioscos.md.
"""
from planos import *

MARCA = {"nombre": "KIOSCOS", "color": "#1F6B4C", "claro": "#F3EBD8", "oscuro": "#10281F", "acento": "#FFD95A"}
G = Guion("kioscos", MARCA)
CA, BA, MESA, GOB = "f_paseo", "aerial_town_avenue", "calculator_papers", "government_building"


def P(de, pasos, items, clips=None, **k):
    if clips == [CA]:
        P.n += 1
        if P.n % 3 == 0:
            clips = [BA]
        k.setdefault("luz", 0.68)
    G.plano(de, pasos, items, clips=clips, **k)


P.n = 0
BOE72 = "Orden de 22-4-1972, BOE 13-5-1972"
CMT = "Comisionado para el Mercado de Tabacos"

